let proto = { z: 5 };
let point = { x: 3, __proto__: proto };
let a = point.x;
let b = point.z;
a + b;

function add(a, b) {
  var s = a + b;
  return s;
}
var r = add(2, 3);
r;

let sum = 0;
for (const v of [10, 20]) {
  sum = sum + v;
}
sum;

function check(n) {
  if (n < 0) throw new RangeError("negative");
  return n;
}
let msg;
try {
  check(-1);
} catch (e) {
  msg = e.message;
}
msg;

// expect: normal: "function|TypeError"
// IsCallable (§7.2.3), asked by EvaluateCall of a callee that is an Object: a function
// has a [[Call]] internal method (step 2 returns true); an ordinary object has none,
// step 3 returns false, and the call throws a TypeError.
function f() { return "function"; }
var o = {};
var r = f();
try { o(); } catch (e) { r += "|" + e.constructor.name; }
r;

// S2 end to end: reading a let binding before its declaration throws a ReferenceError.
// expect: normal: "ReferenceError"
try { t; let t = 1; } catch (e) { e.name }

var s = 0;
for (let i = 0; i < 3; i++) {
  s = s + i;
}
while (s > 1) s = s - 2;

var o = {};
Object.defineProperty(o, "v", { get: function () {
  var k = 41;
  return k + 1;
} });
var w = o.v;

var a = [1, 2].map(function (x) {
  var y = x * 10;
  return y;
});
var b = a.map(function (x) { return x + 1; });

var a = 1;
var b = eval("var c = a + 1;\nc * 2");
var f = new Function("x", "var y = x + 1;\nreturn y * 2;");
var r = f(b);
print(r);

function* g() {
  var a = 1;
  yield a;
  a = a + 1;
  yield a;
}
var it = g();
var x = it.next().value;
x = x + it.next().value;

"use strict"
.length;
debugger;

debugger;
var o = {a: 1};
debugger;
o.a = 2;
