// Flags: --bundle

// JS_BUNDLE_MODULE:lib/math.mjs
export function double(x) {
  return x * 2;
}
// JS_BUNDLE_MODULE:lib/show.mjs
import { double } from "./math.mjs";
export function show(x) {
  print(double(x));
}
// JS_BUNDLE_MODULE_ENTRYPOINT:main.mjs
import { show } from "./lib/show.mjs";
show(21);

// Proxy exotic objects (§10.5): every trap is called with the target, and a
// missing trap forwards to the target. Reflect.set with the Proxy as receiver
// defines the property through the Proxy (OrdinarySetWithOwnDescriptor, §10.1.9.2).
// expect: normal: "get:a,has:a,set:b,getOwnPropertyDescriptor:b,defineProperty:b,delete:b,ownKeys,getOwnPropertyDescriptor:a,defineProperty:c,getPrototypeOf,setPrototypeOf,isExtensible,preventExtensions|1|true|2|a,c|true"
var log = [];
var target = { a: 1 };
var handler = {
  get: function (t, k, r) { log.push("get:" + String(k)); return Reflect.get(t, k, r); },
  has: function (t, k) { log.push("has:" + String(k)); return k in t; },
  set: function (t, k, v, r) { log.push("set:" + String(k)); return Reflect.set(t, k, v, r); },
  deleteProperty: function (t, k) { log.push("delete:" + String(k)); return delete t[k]; },
  ownKeys: function (t) { log.push("ownKeys"); return Reflect.ownKeys(t); },
  getOwnPropertyDescriptor: function (t, k) {
    log.push("getOwnPropertyDescriptor:" + String(k));
    return Object.getOwnPropertyDescriptor(t, k);
  },
  defineProperty: function (t, k, d) { log.push("defineProperty:" + String(k)); return Reflect.defineProperty(t, k, d); },
  getPrototypeOf: function (t) { log.push("getPrototypeOf"); return Object.getPrototypeOf(t); },
  setPrototypeOf: function (t, p) { log.push("setPrototypeOf"); return Reflect.setPrototypeOf(t, p); },
  isExtensible: function (t) { log.push("isExtensible"); return Object.isExtensible(t); },
  preventExtensions: function (t) { log.push("preventExtensions"); return Reflect.preventExtensions(t); }
};
var p = new Proxy(target, handler);
var a = p.a;
var has = "a" in p;
p.b = 2;
var b = target.b;
delete p.b;
Reflect.ownKeys(p);
Object.getOwnPropertyDescriptor(p, "a");
Object.defineProperty(p, "c", { value: 3, configurable: true, enumerable: true });
Object.getPrototypeOf(p);
Object.setPrototypeOf(p, Object.prototype);
Object.isExtensible(p);
Object.preventExtensions(p);
log.join(",") + "|" + a + "|" + has + "|" + b + "|" + Object.keys(target).join(",") + "|" +
  (Object.isExtensible(target) === false)

// expect: normal: "0"
// print: 0,1,2,3,4
// print: b,c,a,d
// Promise jobs run in FIFO order after the Script (§9.5, §27.5.2); resolving
// with a promise takes two more jobs (NewPromiseResolveThenableJob, then the
// reaction that resolves).
var log = [];
Promise.resolve().then(function () { log.push(1); }).then(function () { log.push(3); });
Promise.resolve().then(function () { log.push(2); }).then(function () { log.push(4); print(log.join(",")); });
var order = [];
var p = Promise.resolve(1);
new Promise(function (r) { r(p); }).then(function () { order.push("a"); });
p.then(function () { order.push("b"); }).then(function () { order.push("c"); })
  .then(function () { order.push("d"); print(order.join(",")); });
log.push(0);
log.join(",")

// `using` declarations (§14.3.1) dispose their resources in reverse order when
// the Block ends (DisposeResources, §7.5.5); DisposableStack.prototype.use too.
// expect: normal: "b,a,s"
var log = [];
function res(n) { return { [Symbol.dispose]() { log.push(n); } }; }
{
  using a = res("a"), b = res("b");
}
var stack = new DisposableStack();
stack.use(res("s"));
stack.dispose();
log.join()

// The with statement (§14.11): names resolve in the object first, assignments
// go to its properties, @@unscopables hides names, and the scope ends after.
// expect: normal: "1,5,outer,undefined,2"
var v = "outer", a = 0, o = { a: 1, v: 2 };
var r = [];
with (o) { r.push(a); v = 5; }
r.push(o.v, v);
o[Symbol.unscopables] = { a: true };
with (o) { r.push(typeof b); a = 2; }
r.push(a);
r.join()

// On a web-browser host, a FunctionDeclaration in a Block is also a var of the
// enclosing function (§B.3.2.1), set when the declaration is evaluated.
// args: --web-browser
// expect: normal: "undefined,function,2"
function g() {
  var before = typeof f;
  { function f() { return 2; } }
  return [before, typeof f, f()].join();
}
g()

// Two GroupSpecifiers with one CapturingGroupName are a SyntaxError unless
// some Disjunction has them in different Alternatives (§22.2.1.1, Pattern ::
// Disjunction; MightBothParticipate, §22.2.1.4), in nested Disjunctions too,
// for new RegExp and for a RegularExpressionLiteral (§13.2.7.2).
// expect: normal: undefined
// print: SyntaxError SyntaxError SyntaxError ok ok
// print: SyntaxError
// print: y
function t(s) { try { new RegExp(s); return "ok"; } catch (e) { return e.name; } }
print(t("(?:(?<a>x)|y)(?:z|(?<a>w))") + " " + t("(?<a>x)(?:|(?<a>z))") + " " + t("(?<a>(?<a>x))") + " " +
  t("(?<a>x)|(?<a>y)") + " " + t("((?<a>x)|y|(?:z|(?<a>w)))"));
try { eval("/(?:(?<a>x)|y)(?:z|(?<a>w))\\k<a>/"); print("parsed"); } catch (e) { print(e.name); }
print(/(?:(?<a>x)|(?<a>y))\k<a>/.exec("yy").groups.a);

// module: yes
// expect: normal: undefined
// print: before
// print: 3 after
// A Module whose body contains `await` has [[HasTLA]] true: ExecuteModule
// runs it with AsyncBlockStart (§16.2.1.7.3.2 step 4.b), so the body suspends
// at each Await and the rest of it runs from the promise jobs.
print("before");
var a = await Promise.resolve(1);
var b = await 2;
print((a + b) + " after");

// expect: normal: undefined
// print: function,2,undefined
// print: sync
// print: promise
// print: t0
// print: t5
// print: t10,true
// setTimeout (the test host's global) performs HostEnqueueTimeoutJob of a Job that calls its callback:
// the promise Jobs run first, then each timeout Job once its delay has passed; a negative delay is 0.
var before = Date.now();
print([typeof setTimeout, setTimeout.length, typeof setTimeout(function () { print("t0"); }, -3)].join(","));
setTimeout(function () { print("t5"); }, 5);
setTimeout(function () { print(["t10", Date.now() - before >= 10].join(",")); }, 10);
Promise.resolve().then(function () { print("promise"); });
print("sync");

// expect: normal: "10,30,50|2,3|3,4,5|1,1,2,2|15|true,false,3|1+2|a,b,c|1:x,2:y|u,v,w"
// Iterator helpers (§27.1.3.3), Iterator.from, Iterator.concat and Iterator.zip (§27.1.3.2).
var parts = [];
parts.push([1, 2, 3, 4, 5].values().filter(function (x) { return x % 2; })
  .map(function (x) { return x * 10; }).toArray().join(","));
parts.push([1, 2, 3, 4].values().drop(1).take(2).toArray().join(","));
parts.push([1, 2, 3, 4, 5].values().drop(2).toArray().join(","));
parts.push([1, 2].values().flatMap(function (x) { return [x, x]; }).toArray().join(","));
parts.push([1, 2, 3, 4, 5].values().reduce(function (a, b) { return a + b; }));
parts.push([[1, 2].values().some(function (x) { return x > 1; }),
  [1, 2].values().every(function (x) { return x > 1; }),
  [1, 2, 3].values().find(function (x) { return x > 2; })].join(","));
var seen = [];
[1, 2].values().forEach(function (x) { seen.push(x); });
parts.push(seen.join("+"));
var n = 0;
var plain = { next: function () { n++; return n <= 3 ? { value: "abc"[n - 1], done: false } : { done: true }; } };
parts.push(Iterator.from(plain).toArray().join(","));
parts.push(Iterator.zip([[1, 2], ["x", "y", "z"]]).map(function (p) { return p.join(":"); }).toArray().join(","));
parts.push(Iterator.concat(["u"], ["v", "w"]).toArray().join(","));
parts.join("|")

// expect: normal: undefined
// print: -Infinity,-Infinity,Infinity,-Infinity,Infinity,Infinity,-Infinity
// Number::multiply step 6 gives 𝔽(0) = +0 for +0 × -5; the clause's
// description (IEEE 754-2019) and every engine give -0 (Erratum
// NumberMultiplyZeroSign, read by default as proposed: no test262 assertion
// covers the case). A product that underflows keeps
// its sign by 𝔽 itself.
print(String([1 / (0 * -5), 1 / (-5 * 0), 1 / (0 * 5), 1 / (-0 * 5), 1 / (-0 * -5), 1 / (0 * 0),
  1 / (1e-300 * -1e-300)]));

// expect: normal: "1,2,3|3,2,1"
// A comparator that returns ±Infinity (Erratum SortInfiniteComparator): under
// the test262 reading the order is the host's, and the test host's goes by the
// result's sign.
var r = [];
r.push([3, 1, 2].sort(function (a, b) { return a < b ? -Infinity : a > b ? Infinity : 0; }).join());
r.push([1, 3, 2].sort(function (a, b) { return a < b ? Infinity : a > b ? -Infinity : 0; }).join());
r.join("|");

// IsLabelledFunction takes "the |LabelledItem| of" a |Statement| node through
// its unit chain (Erratum UnitChainChild, test262's reading): the labelled
// function in an if body is the Early Error of sec-if-statement-static-semantics-early-errors.
// args: --web-browser
// expect: throw: SyntaxError
if (1) l: function f() {}

async function h() {
  var a = 1;
  await a;
  a = a + 1;
  return a;
}
var p = h();
p.then(function (v) { print(v); });
var z = 3;

// Atomics.wait on an agent that can block (§25.4.3.14, SuspendThisAgent
// §25.4.3.11): with one agent nothing notifies the waiter, so it wakes when
// the host's clock reaches its timeout time. Erratum DoWaitSyncTimeout: the
// woken waiter's [[Result]] is "timed-out" and it leaves the WaiterList, so a
// second wait on the same location does not fail AddWaiter step 2's Assert
// and a later Atomics.notify finds no waiter.
// args: --can-block
// expect: normal: undefined
// print: timed-out,timed-out,true,true,0 ; not-equal
var i32 = new Int32Array(new SharedArrayBuffer(8));
var t0 = Date.now();
var first = Atomics.wait(i32, 0, 0, 10);
var t1 = Date.now();
var second = Atomics.wait(i32, 0, 0, 5);
var t2 = Date.now();
var notified = Atomics.notify(i32, 0);
Atomics.store(i32, 1, 3);
print([first, second, t1 - t0 >= 10, t2 - t1 >= 5, notified].join() + " ; " + Atomics.wait(i32, 1, 0, 10));
void 0;

// expect: normal: undefined
// print: body: SyntaxError
// print: params: SyntaxError
// print: generator body: SyntaxError
// CreateDynamicFunction steps 18-29: no goal it parses with applies
// AllPrivateIdentifiersValid (Erratum CreateDynamicFunctionPrivateIdentifiers).
// The default reading, the proposed one, adds after step 25
// "If AllPrivateIdentifiersValid of _body_ with argument « » is false, throw a
// SyntaxError exception" and the same of _params_ (spec/formal/readings.emu):
// engines parse the parameters and the body as one source text and throw for
// both. The test262 reading checks the body only, which is all test262's
// built-ins/Function/private-identifiers-not-empty.js asserts
// (dynamic_function_private_identifiers_test262.js); the literal text checks
// neither (dynamic_function_private_identifiers_literal.js).
try { new Function("o", "return o.#f"); print("body: no error"); }
catch (e) { print("body: " + e.constructor.name); }
try { new Function("a = {}.#g", ""); print("params: no error"); }
catch (e) { print("params: " + e.constructor.name); }
var GeneratorFunction = Object.getPrototypeOf(function* () {}).constructor;
try { GeneratorFunction("o", "yield o.#h"); print("generator body: no error"); }
catch (e) { print("generator body: " + e.constructor.name); }

// expect: normal: "true|false"
// Two cells with one unregister token, in a row (Erratum
// UnregisterIteratesCopy): the test262 reading removes both.
var fr = new FinalizationRegistry(function () {});
var token = {};
fr.register({}, 1, token);
fr.register({}, 2, token);
[fr.unregister(token), fr.unregister(token)].join("|");

// expect: stop: assertFailed sec-getutcepochnanoseconds#0 4
// UTC ( t ) of a large finite local time: setHours(1e21) gives t = 3.6e24,
// GetUTCEpochNanoseconds step 1's MakeDay finds no time value on the month's
// first day (NaN), and the Assert of its step 4 fails. No test262 test
// reaches it, and the default reading is the text as written (Erratum
// GetUTCEpochNanosecondsNaN), so the run stops.
// Engines give NaN. The UTC setter does not call UTC ( t ): NaN.
print(String(new Date(0).setUTCHours(1e21)));
print(String(new Date(0).setHours(1e21)));

// expect: stop: assertFailed sec-getmatchstring#0 1
// RegExpBuiltinExec with /u and lastIndex on the trailing surrogate of a pair:
// step 13.b starts at the code point that contains it, the empty pattern
// matches there with [[EndIndex]] 0, and step 24's Match Record { 1, 0 } fails
// GetMatchString step 1's Assert. No test262 test sets lastIndex inside a
// pair before an empty match; the default reading is the text as written
// (Erratum GetMatchStringStartAfterEnd), so the run stops.
// V8 and SpiderMonkey report index 0; JavaScriptCore reports index 1.
// (The non-empty case, which does not stop, is
// regexp_lastindex_inside_pair_nonempty.js.)
var r = /(?:)/gu;
r.lastIndex = 1;
r.exec("\u{1F600}");

// expect: stop: assertFailed sec-jobs -
// NewPromiseReactionJob 1.i returns `? Call(promiseCapability.[[Resolve]], …)`;
// with a species constructor whose resolve throws, the Job returns a throw
// completion, which §9.5 says a Job must not. No test262 test makes a
// reaction Job's resolving function throw; the default reading is the text
// as written (Erratum PromiseJobAbruptCompletion), so the run
// stops. (Engine hosts differ: node goes on silently; the SpiderMonkey shell
// and Bun, with JavaScriptCore, report the throw and go on.)
function Bad(executor) {
  executor(function () { throw new Error("boom"); }, function () {});
}
Bad[Symbol.species] = Bad;
var p = Promise.resolve(1);
p.constructor = Bad;
p.then(function (v) { print("handler " + v); return v; });
Promise.resolve(3).then(function () { print("a later Job"); });

// args: --bundle
// expect: throw: SyntaxError
// ECMA-262 as it stands has no `import defer` and no `import.defer()`: this is a SyntaxError.
// With proposal-defer-import-eval applied (branch proposal-defer-import-eval; the debugger's build
// "Proposal: import defer") it completes normally and prints:
//   [object Deferred Module]
//   main starts; heavy evaluates; read 42; read again 42
// proposal-defer-import-eval: `import defer * as heavy` loads and links heavy.mjs with the graph but evaluates it at the
// first read of an export (the namespace's [[Get]]: GetModuleExportsList, EvaluateModuleSync); %Symbol.toStringTag%
// is read without evaluating it (IsSymbolLikeNamespaceKey), and is "Deferred Module" (ModuleNamespaceCreate).
// JS_BUNDLE_MODULE:log.mjs
export const log = [];
// JS_BUNDLE_MODULE:heavy.mjs
import { log } from "./log.mjs";
log.push("heavy evaluates");
export const answer = 42;
// JS_BUNDLE_MODULE_ENTRYPOINT:main.mjs
import { log } from "./log.mjs";
import defer * as heavy from "./heavy.mjs";
log.push("main starts");
print(Object.prototype.toString.call(heavy));
log.push("read " + heavy.answer);
log.push("read again " + heavy.answer);
print(log.join("; "));

// args: --bundle
// expect: throw: SyntaxError
// ECMA-262 as it stands has no `import defer` and no `import.defer()`: this is a SyntaxError.
// With proposal-defer-import-eval applied (branch proposal-defer-import-eval; the debugger's build
// "Proposal: import defer") it completes normally and prints:
//   promise settled; then in ns: false; dep evaluates; x is 1
// proposal-defer-import-eval: `import.defer()` settles with a deferred namespace without evaluating the module
// (ContinueDynamicImport, GatherAsynchronousTransitiveDependencies finds nothing); "then" is not an export of a
// deferred namespace (GetModuleNamespace), so the promise's resolution does not evaluate it either
// (IsSymbolLikeNamespaceKey); reading `x` does.
// JS_BUNDLE_MODULE:dep.mjs
globalThis.order.push("dep evaluates");
export function then(resolve) { globalThis.order.push("then called"); resolve("oops"); }
export const x = 1;
// JS_BUNDLE_MODULE_ENTRYPOINT:main.mjs
globalThis.order = [];
const ns = await import.defer("./dep.mjs");
order.push("promise settled");
order.push("then in ns: " + ("then" in ns));
order.push("x is " + ns.x);
print(order.join("; "));

// args: --bundle
// expect: throw: SyntaxError
// ECMA-262 as it stands has no `import defer` and no `import.defer()`: this is a SyntaxError.
// With proposal-defer-import-eval applied (branch proposal-defer-import-eval; the debugger's build
// "Proposal: import defer") it completes normally and prints:
//   before access: b, e, d, a
//   after access: b, e, d, a, f, c
// proposal-defer-import-eval, the README's graph: c is deferred, but its dependency d has top-level await, so d and
// its dependency e evaluate with the graph (InnerModuleEvaluation, GatherAsynchronousTransitiveDependencies); f and
// c wait for the first read of c's namespace.
// JS_BUNDLE_MODULE:order.mjs
export const order = [];
// JS_BUNDLE_MODULE:b.mjs
import { order } from "./order.mjs";
order.push("b");
// JS_BUNDLE_MODULE:e.mjs
import { order } from "./order.mjs";
order.push("e");
// JS_BUNDLE_MODULE:d.mjs
import { order } from "./order.mjs";
import "./e.mjs";
await 0;
order.push("d");
// JS_BUNDLE_MODULE:f.mjs
import { order } from "./order.mjs";
order.push("f");
// JS_BUNDLE_MODULE:c.mjs
import { order } from "./order.mjs";
import "./d.mjs";
import "./f.mjs";
order.push("c");
export let value = 2;
// JS_BUNDLE_MODULE_ENTRYPOINT:a.mjs
import { order } from "./order.mjs";
import "./b.mjs";
import defer * as c from "./c.mjs";
order.push("a");
print("before access: " + order.join(", "));
c.value;
print("after access: " + order.join(", "));

// JS_BUNDLE_MODULE:greeting.txt
Hello from ECMA-262 Import Text!
// JS_BUNDLE_MODULE_ENTRYPOINT:main.mjs
import greeting from "./greeting.txt" with { type: "text" };
const dyn = await import("./greeting.txt", { with: { type: "text" } });
print(greeting.trim() + " | cached=" + (greeting === dyn.default));

const events = [];
const thenable = {
  then(resolve) {
    events.push("then-called");
    resolve(42);
  }
};
const p = Promise.resolve(thenable);
Promise.resolve().then(() => events.push("microtask"));
p.then((v) => {
  events.push("resolved:" + v);
  print(events.join(" -> "));
});
void 0;

// JS_BUNDLE_MODULE:log.mjs
export const events = [];
// JS_BUNDLE_MODULE:heavy.mjs
import { events } from "./log.mjs";
events.push("heavy");
export const x = 99;
// JS_BUNDLE_MODULE:barrel.mjs
import { events } from "./log.mjs";
export defer { x } from "./heavy.mjs";
events.push("barrel");
// JS_BUNDLE_MODULE_ENTRYPOINT:main.mjs
import { events } from "./log.mjs";
import * as barrel from "./barrel.mjs";
print("after barrel import: " + events.join(","));
const v = barrel.x;
print("after reading barrel.x=" + v + ": " + events.join(","));

const imm = JSON.parse('{"x":[1,{"y":2}],"__proto__":{"safe":true}}', { freeze: true });
const nullOnly = JSON.parse('{"mutable":1}', { nullPrototypeObjects: true });
nullOnly.mutable = 2;
print([
  "frozen=" + Object.isFrozen(imm.x[1]),
  "proto=" + Object.getPrototypeOf(imm),
  "ownProto=" + imm.__proto__.safe,
  "nullMutable=" + nullOnly.mutable
].join(", "));

// JS_BUNDLE_MODULE:dep.js
export let runs = 0;
runs++;
export const answer = 42;
// JS_BUNDLE_MODULE_ENTRYPOINT:main.js
import source depSrc from "./dep.js";
const dynSrc = await import.source("./dep.js");
const ns1 = await import(depSrc);
const ns2 = await import("./dep.js");
print([
  depSrc[Symbol.toStringTag],
  "sameSource=" + (depSrc === dynSrc),
  "sameNs=" + (ns1 === ns2),
  "runs=" + ns1.runs,
  "answer=" + ns1.answer
].join(", "));

"use strict";
const ab = new ArrayBuffer(4);
new Uint8Array(ab).set([10, 20, 30, 40]);
const sliced = ab.sliceToImmutable(1, 3);
const moved = ab.transferToImmutable(6);
const view = new Uint8Array(moved);
let writeThrew = false;
try { view[0] = 99; } catch (e) { writeThrew = e instanceof TypeError; }
print([
  "slice=" + Array.from(new Uint8Array(sliced)).join(","),
  "detached=" + ab.detached,
  "immutable=" + moved.immutable,
  "writeThrew=" + writeThrew
].join(", "));

const err = new Error("connect failed", { code: "ECONNREFUSED", cause: "timeout" });
const sup = new SuppressedError(err, new TypeError("close failed"), "disposal failed", { code: "EDISPOSE" });
const desc = Object.getOwnPropertyDescriptor(err, "code");
print([
  "code=" + err.code,
  "enumerable=" + desc.enumerable,
  "suppressedCode=" + sup.code
].join(", "));

// (1 + 2^-52) * (1 - 2^-52) = 1 - 2^-104 in R.
// Naive a * b + (-1) rounds a * b to 1 first and loses the -2^-104 residual!
const a = 1 + 2 ** -52;
const b = 1 - 2 ** -52;
